SELECT to_base62(inventory.id) AS "cardSecretId",
       to_base62(inventory.sku_id) AS "skuId",
       encode(inventory.sku_id, 'hex') AS "skuIdHex",
       inventory.batch_no AS "batchNo",
       inventory.import_source AS "importSource",
       inventory.status AS "inventoryStatus",
       delivery.status AS "deliveryStatus",
       COALESCE(delivery.order_no, inventory.order_no) AS "orderNo",
       orders.status AS "orderStatus",
       COALESCE(delivery.user_id, inventory.user_id) AS "userId",
       inventory.sold_at AS "soldAt",
       delivery.delivered_at AS "deliveredAt",
       inventory.created_at AS "createdAt",
       inventory.created_by_admin_username AS "createdByAdminUsername",
       inventory.created_by_admin_email AS "createdByAdminEmail"
FROM card_secret_inventory inventory
LEFT JOIN order_card_secret_delivery delivery ON delivery.card_secret_id = inventory.id
LEFT JOIN trade_order orders ON orders.order_no = COALESCE(delivery.order_no, inventory.order_no)


        AND inventory.sku_id = #{skuId}


        AND encode(inventory.sku_id, 'hex') IN

            #{skuIdHex}



        AND inventory.batch_no = #{batchNo}


        AND inventory.status = #{inventoryStatus}


        AND delivery.status = #{deliveryStatus}


        AND COALESCE(delivery.order_no, inventory.order_no) = #{orderNo}


        AND COALESCE(delivery.user_id, inventory.user_id) = #{userId}


        AND orders.status = #{orderStatus}


        AND inventory.created_by_admin_username = #{createdByAdminUsername}


        AND inventory.import_source = #{importSource}


        AND (
            (#{currentAdminUsername} IS NOT NULL AND inventory.created_by_admin_username = #{currentAdminUsername})
            OR (#{currentAdminEmail} IS NOT NULL AND inventory.created_by_admin_email = #{currentAdminEmail})
            OR (#{currentAdminPhone} IS NOT NULL AND inventory.created_by_admin_phone = #{currentAdminPhone})
        )


        AND 1 = 0


ORDER BY inventory.created_at DESC, inventory.id DESC

SELECT to_base62(delivery.id) AS "deliveryId", to_base62(delivery.card_secret_id) AS "cardSecretId", to_base62(delivery.sku_id) AS "skuId", encode(delivery.sku_id, 'hex') AS "skuIdHex", delivery.order_no AS "orderNo", orders.status AS "orderStatus", delivery.user_id AS "userId", inventory.status AS "inventoryStatus", delivery.status AS "deliveryStatus", delivery.delivered_at AS "deliveredAt", delivery.revoked_at AS "revokedAt", delivery.refunded_at AS "refundedAt", delivery.replaced_at AS "replacedAt", inventory.created_by_admin_username AS "createdByAdminUsername" FROM order_card_secret_delivery delivery INNER JOIN card_secret_inventory inventory ON inventory.id = delivery.card_secret_id LEFT JOIN trade_order orders ON orders.order_no = delivery.order_no
AND delivery.sku_id = #{skuId}
AND encode(delivery.sku_id, 'hex') IN
#{skuIdHex}
AND delivery.order_no = #{orderNo}
AND delivery.user_id = #{userId}
AND delivery.status = #{deliveryStatus}
AND orders.status = #{orderStatus}
AND inventory.created_by_admin_username = #{createdByAdminUsername}
AND ( (#{currentAdminUsername} IS NOT NULL AND inventory.created_by_admin_username = #{currentAdminUsername}) OR (#{currentAdminEmail} IS NOT NULL AND inventory.created_by_admin_email = #{currentAdminEmail}) OR (#{currentAdminPhone} IS NOT NULL AND inventory.created_by_admin_phone = #{currentAdminPhone}) )
AND 1 = 0
ORDER BY delivery.delivered_at DESC, delivery.id DESC
